
.panel {
  width: 100%;
  max-width: 680px;
  margin: 0 auto;
  background-color: var(--c-bg);
  border: 1px solid var(--c-border);
  border-radius: 10px;
  overflow: hidden;
  font-family: var(--font-main);
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.45;
  transition: var(--t-theme), box-shadow 0.6s ease;

  /* CLIMAX：边缘红光呼吸 */
  &.climax {
    animation: climax-glow 1.6s ease-in-out infinite;
  }
}

.panel-body {
  padding: 10px 12px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

@keyframes climax-glow {
  0%,
  100% {
    box-shadow: 0 0 0 1px var(--c-danger), 0 0 10px rgba(217, 80, 80, 0.25);
  }

  50% {
    box-shadow: 0 0 0 2px var(--c-danger), 0 0 22px rgba(217, 80, 80, 0.55);
  }
}
