
.header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  cursor: pointer;
  user-select: none;
  background-color: var(--c-surface);
  border-bottom: 1px solid var(--c-border);
  transition: var(--t-theme);

  &:hover {
    background-color: var(--c-surface-2);
  }
}

.who {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.name {
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.5px;
}

.partner {
  font-size: 11px;
  color: var(--c-text-muted);

  &.active {
    color: var(--c-accent);
  }
}

.minis {
  display: flex;
  gap: 8px;
  margin-left: auto;
}

.mini {
  display: flex;
  align-items: center;
  gap: 4px;
}

.mini-label {
  font-family: var(--font-num);
  font-size: 9px;
  color: var(--c-text-muted);
}

.mini-track {
  width: 52px;
  height: 6px;
  border-radius: 3px;
  background-color: var(--c-surface-2);
  overflow: hidden;
}

.mini-fill {
  display: block;
  height: 100%;
  border-radius: 3px;
  transition: width 0.6s ease;

  &.excite {
    background-color: var(--c-accent);
  }

  &.cum {
    background-color: var(--c-primary);

    &.hot {
      background-color: var(--c-danger);
      animation: hot-pulse 0.9s ease-in-out infinite;
    }
  }
}

.mini-num {
  font-family: var(--font-num);
  font-size: 10px;
  color: var(--c-text-muted);
  width: 2ch;
  text-align: right;
}

.right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stage-badge {
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid var(--c-border);
  color: var(--c-text-muted);
  background-color: transparent;
  transition: var(--t-theme);

  &.stage-resist {
    color: var(--c-primary);
    border-color: var(--c-primary);
  }

  &.stage-waver {
    color: var(--c-accent);
    border-color: var(--c-accent);
  }

  &.stage-edge {
    color: var(--c-danger);
    border-color: var(--c-danger);
    animation: hot-pulse 1.4s ease-in-out infinite;
  }

  &.stage-submit {
    color: var(--c-warm);
    border-color: var(--c-warm);
    background-color: color-mix(in srgb, var(--c-warm) 14%, transparent);
  }
}

.chevron {
  font-size: 11px;
  color: var(--c-text-muted);
  transition: transform 0.3s ease;

  &.flipped {
    transform: rotate(-90deg);
  }
}

@keyframes hot-pulse {
  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0.45;
  }
}
