
.section {
  background-color: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 8px 10px;
  transition: var(--t-theme);
}

.section-head {
  font-family: var(--font-num);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--c-primary);
  margin-bottom: 7px;
}

.section-sub {
  font-family: var(--font-main);
  font-weight: 400;
  font-size: 10px;
  color: var(--c-text-muted);
  letter-spacing: 0;
}

.gauges {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 7px 14px;
}

.gauge-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 2px;
}

.gauge-label {
  font-family: var(--font-num);
  font-size: 10px;
  color: var(--c-text-muted);
}

.gauge-cn {
  font-family: var(--font-main);
  font-size: 10px;
  color: var(--c-text-muted);
}

.gauge-num {
  font-family: var(--font-num);
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text);
}

.gauge-track {
  height: 7px;
  border-radius: 3.5px;
  background-color: var(--c-surface-2);
  overflow: hidden;
}

.gauge-fill {
  height: 100%;
  border-radius: 3.5px;
  background-color: var(--c-primary);
  transition: width 0.6s ease, background-color 0.6s ease;
}

.gauge.hot {
  .gauge-num,
  .gauge-label {
    color: var(--c-danger);
  }

  .gauge-fill {
    background-color: var(--c-danger);
    animation: gauge-pulse 0.9s ease-in-out infinite;
  }
}

@keyframes gauge-pulse {
  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0.5;
  }
}
