
.section {
  background-color: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 8px 10px;
  transition: var(--t-theme);
}

.section-head {
  font-family: var(--font-num);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--c-primary);
  margin-bottom: 7px;
}

.section-sub {
  font-family: var(--font-main);
  font-weight: 400;
  font-size: 10px;
  color: var(--c-text-muted);
  letter-spacing: 0;
}

.empty {
  font-size: 11px;
  color: var(--c-text-muted);
}

.buffs {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.buff {
  border-left: 3px solid var(--c-good);
  background-color: var(--c-surface-2);
  border-radius: 0 6px 6px 0;
  padding: 4px 8px;

  &.is-bad {
    border-left-color: var(--c-bad);
  }
}

.buff-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.buff-name {
  font-family: var(--font-num);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--c-good);
}

.buff.is-bad .buff-name {
  color: var(--c-bad);
}

.buff-layers {
  font-size: 10px;
  color: var(--c-accent);
}

.buff-kind {
  font-size: 9px;
  color: var(--c-text-muted);
}

.buff-effect {
  font-size: 11px;
  color: var(--c-text);
  margin-top: 1px;
}

.buff-duration {
  font-size: 10px;
  color: var(--c-text-muted);
}
