
.section {
  background-color: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 8px 10px;
  transition: var(--t-theme);
}

.section-head {
  font-family: var(--font-num);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--c-primary);
  margin-bottom: 6px;
}

.section-sub {
  font-family: var(--font-main);
  font-weight: 400;
  font-size: 10px;
  color: var(--c-text-muted);
  letter-spacing: 0;
}

.rows {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 18px;
}

.row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
}

.c-name {
  font-family: var(--font-num);
  font-weight: 600;
  color: var(--c-text);
}

.c-sep {
  width: 1px;
  height: 10px;
  background-color: var(--c-border);
}

.c-value {
  font-family: var(--font-num);
  color: var(--c-text-muted);

  i {
    font-size: 9px;
    color: var(--c-accent);
  }
}

.c-divider {
  color: var(--c-border);
}

.empty {
  font-size: 11px;
  color: var(--c-text-muted);
}
