
.section {
  background-color: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 8px 10px;
  transition: var(--t-theme);
}

.section-head {
  font-family: var(--font-num);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--c-primary);
  margin-bottom: 7px;
}

.section-sub {
  font-family: var(--font-main);
  font-weight: 400;
  font-size: 10px;
  color: var(--c-text-muted);
  letter-spacing: 0;
}

.fetishes {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  gap: 7px 14px;
}

.f-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 3px;
}

.f-name {
  font-family: var(--font-num);
  font-size: 11px;
  font-weight: 600;
  color: var(--c-text);
}

.f-cn {
  font-family: var(--font-main);
  font-weight: 400;
  font-size: 10px;
  color: var(--c-text-muted);
  margin-left: 4px;
}

.f-lv-blocks {
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.lv-block {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background-color: var(--c-surface-2);
  border: 1px solid var(--c-border);

  &.lit {
    background-color: var(--c-accent);
    border-color: var(--c-accent);
  }

  &.lit.max {
    background-color: var(--c-danger);
    border-color: var(--c-danger);
  }
}

.f-lv-num {
  font-family: var(--font-num);
  font-size: 9px;
  color: var(--c-text-muted);
  margin-left: 3px;
}

.f-track {
  height: 5px;
  border-radius: 2.5px;
  background-color: var(--c-surface-2);
  overflow: hidden;
}

.f-fill {
  height: 100%;
  border-radius: 2.5px;
  background-color: var(--c-accent);
  opacity: 0.8;
  transition: width 0.6s ease;
}

.f-progress-num {
  font-family: var(--font-num);
  font-size: 9px;
  color: var(--c-text-muted);
  text-align: right;
  margin-top: 1px;
}

/* 接近升级 / Cannot-Refuse：进度高亮脉冲 */
.fetish.close {
  .f-fill {
    background-color: var(--c-danger);
    animation: fetish-pulse 1.2s ease-in-out infinite;
  }

  .f-progress-num {
    color: var(--c-danger);
  }
}

@keyframes fetish-pulse {
  0%,
  100% {
    opacity: 0.9;
  }

  50% {
    opacity: 0.45;
  }
}
